#!/bin/sh
# SPDX-License-Identifier: GPL-2.0-or-later
# Activates the Blossom QtQuick Controls style for the Plasma session.
# Installed to <sysconf>/plasma-workspace/env/ (system-wide) or
# ~/.config/plasma-workspace/env/ (per-user, no root needed).
export QT_QUICK_CONTROLS_STYLE=org.blossomos.style
